root.addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();e.stopPropagation();const tabs=['playback','practice','lesson'];const i=tabs.indexOf(ui.optionsTab);ui.optionsTab=e.key==='Home'?tabs[0]:e.key==='End'?tabs[2]:tabs[(i+(e.key==='ArrowRight'?1:2))%3];render();root.querySelector('[role=tab][aria-selected=true]')?.focus();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();action(e.target.dataset.action,e.target.dataset,e);}});
root.addEventListener('input',e=>{const t=e.target;if(t.id==='library-search'){if(ui.view==='home')ui.view='library';ui.search=t.value;const pos=t.selectionStart;render();const field=document.getElementById('library-search');field?.focus();field?.setSelectionRange(pos,pos);}if(['import-url','import-title','import-speaker','transcript-text','import-offset','import-grouping'].includes(t.id)){const a=ui.import;if(t.id==='import-url')a.url=t.value;if(t.id==='import-title')a.title=t.value;if(t.id==='import-speaker')a.speaker=t.value;if(t.id==='transcript-text')a.text=t.value;if(t.id==='import-offset')a.offset=Number(t.value);if(t.id==='import-grouping')a.grouping=t.value;a.preview=null;}if(t.id==='phrase-seek'){t.style.setProperty('--progress',`${Number(t.value)/Number(t.max)*100}%`);const label=document.getElementById('phrase-elapsed');if(label)label.textContent=fmtTime(Number(t.value));}});
root.addEventListener('change',async e=>{const t=e.target;if(t.id==='practice-selection'){const range=document.querySelector('.practice-range-fields');if(range)range.hidden=t.value!=='range';return;}if(t.id==='lesson-audio-file'&&t.files?.[0]){uploadLessonAudio(t.files[0],t.dataset.lessonId);return;}if(t.id==='lesson-media-source'||t.id==='audio-offset'){const lesson=store.data.lessons.find(l=>l.id===t.dataset.lessonId);if(!lesson)return;if(t.id==='audio-offset'&&!Number.isFinite(Number(t.value)))return;store.mutate(()=>{if(t.id==='audio-offset')lesson.audioOffset=Number(t.value);else lesson.mediaSource=t.value;});reloadSource(lesson);return;}if(t.dataset.pref){changePref(t.dataset.pref,t.type==='checkbox'?t.checked:t.value);return;}if(t.id==='transcript-file'&&t.files?.[0]){const f=t.files[0];if(f.size>5_000_000)return toast('Transcript file must be under 5 MB.');ui.import.text=await f.text();ui.import.fileName=f.name;ui.import.preview=null;render();toast(`${f.name} ready to preview.`);return;}if(t.id==='restore-file'&&t.files?.[0]){if(!confirm('Replace your entire library with this backup? Export the current library first if you need it.'))return;try{store.restore(await t.files[0].text());toast('Backup restored.');render();}catch(err){toast(err.message);}return;}if(t.id==='library-filter'){ui.libraryFilter=t.value;render();}if(t.id==='library-sort'){ui.sort=t.value;render();}if(t.id==='speed'){const rate=Number(t.value);if(player.setSpeed(rate))changePref('speed',rate);}if(t.id==='phrase-seek'||t.id==='dialog-phrase-seek'){const p=player.current();if(p)player.seekRecording(p.start+Number(t.value),player.playing);}if(t.id==='recording-seek'||t.id==='dialog-recording-seek')player.seekRecording(Number(t.value),player.playing);if(t.id==='regroup-mode')showRegroup(t.value);});
let touchStart=null;
